import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    degrees = []
    s_values = []

    index = 1
    for i in range(n):
        degrees.append(int(data[index]))
        s_values.append(int(data[index + 1]))
        index += 2

    edges = []
    used = [False] * n

    for i in range(n):
        if degrees[i] == 0:
            continue
        for j in range(i + 1, n):
            if degrees[j] == 0:
                continue
            if (s_values[i] ^ s_values[j]) == (s_values[i] ^ s_values[j] ^ i ^ j):
                edges.append((i, j))
                degrees[i] -= 1
                degrees[j] -= 1
                if degrees[i] == 0:
                    used[i] = True
                if degrees[j] == 0:
                    used[j] = True

    m = len(edges)
    print(m)
    for a, b in edges:
        print(a, b)

if __name__ == "__main__":
    main()
